SELECT sub0.time AS "time", (sub0.value) AS "root.List.*.Value" FROM (SELECT time_bucket('1h', "time", 'Europe/Berlin') AS "time", avg(("__e"."__v" #>> '{}')::double precision) AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" LEFT JOIN LATERAL jsonb_path_query("root.List", '$[*]."Value"'::jsonpath) WITH ORDINALITY AS "__e"("__v", "__n") ON TRUE WHERE "time" > now() - interval '1d' GROUP BY 1 ORDER BY 1 ASC) sub0